import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';
import { ToastService } from '../../core/services/toast.service';

@Component({
  selector: 'app-admin',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="page-container">
      <div class="page-header" style="display:flex;align-items:center;justify-content:space-between;">
        <div>
          <h1 class="page-title">// administration</h1>
          <p class="page-subtitle">Gestion des utilisateurs de la plateforme</p>
        </div>
        <button class="btn btn-primary" (click)="showModal = true">+ Nouvel utilisateur</button>
      </div>

      <div *ngIf="loading" class="loading-overlay"><div class="spinner"></div></div>

      <div class="card" style="padding:0;overflow:hidden;" *ngIf="!loading">
        <table class="data-table">
          <thead>
            <tr>
              <th>Utilisateur</th>
              <th>Email</th>
              <th>Rôle</th>
              <th>Créé le</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngIf="users.length === 0">
              <td colspan="5" style="text-align:center;padding:40px;color:var(--text-faint);">Aucun utilisateur</td>
            </tr>
            <tr *ngFor="let u of users">
              <td>
                <div style="display:flex;align-items:center;gap:8px;">
                  <div class="user-av">{{u.username?.substring(0,2).toUpperCase()}}</div>
                  <span style="font-weight:500;color:var(--text-primary);">{{u.username}}</span>
                </div>
              </td>
              <td>{{u.email}}</td>
              <td>
                <span class="badge" [class]="u.role === 'ADMIN' ? 'high' : 'info'">{{u.role}}</span>
              </td>
              <td style="font-family:var(--font-mono);font-size:11px;">
                {{u.createdAt | date:'dd/MM/yyyy'}}
              </td>
              <td>
                <button class="btn btn-danger btn-sm" (click)="deleteUser(u)"
                        [disabled]="u.role === 'ADMIN'">
                  Supprimer
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Create modal -->
      <div class="modal-overlay" *ngIf="showModal" (click)="showModal=false">
        <div class="modal" (click)="$event.stopPropagation()">
          <div class="modal-header">
            <span class="card-title">Nouvel utilisateur</span>
            <button class="btn btn-secondary btn-sm" (click)="showModal=false">✕</button>
          </div>
          <div class="form-group">
            <label class="form-label">Nom d'utilisateur *</label>
            <input class="form-control" [(ngModel)]="newUser.username" placeholder="username" />
          </div>
          <div class="form-group">
            <label class="form-label">Email *</label>
            <input class="form-control" [(ngModel)]="newUser.email" type="email" placeholder="user@vermeg.com" />
          </div>
          <div class="form-group">
            <label class="form-label">Mot de passe *</label>
            <input class="form-control" [(ngModel)]="newUser.password" type="password" placeholder="••••••••" />
          </div>
          <div class="form-group">
            <label class="form-label">Rôle</label>
            <select class="form-control" [(ngModel)]="newUser.role">
              <option value="USER">USER</option>
              <option value="ADMIN">ADMIN</option>
            </select>
          </div>
          <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:20px;">
            <button class="btn btn-secondary" (click)="showModal=false">Annuler</button>
            <button class="btn btn-primary" (click)="createUser()"
                    [disabled]="!newUser.username || !newUser.email || !newUser.password">
              Créer
            </button>
          </div>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .user-av {
      width: 30px; height: 30px;
      border-radius: 50%;
      background: var(--accent-blue-bg);
      border: 1px solid var(--accent-blue);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 10px;
      font-weight: 700;
      color: var(--accent-blue);
      font-family: var(--font-mono);
    }

    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.6);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 500;
    }

    .modal {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 24px;
      width: 400px;
    }

    .modal-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 20px;
    }
  `]
})
export class AdminComponent implements OnInit {
  users: any[] = [];
  loading   = false;
  showModal = false;
  newUser   = { username: '', email: '', password: '', role: 'USER' };

  constructor(private api: ApiService, private toast: ToastService) {}

  ngOnInit() { this.load(); }

  load() {
    this.loading = true;
    this.api.getUsers().subscribe({
      next: u => { this.users = u; this.loading = false; },
      error: () => { this.loading = false; }
    });
  }

  createUser() {
    this.api.createUser(this.newUser).subscribe({
      next: () => {
        this.toast.success('Utilisateur créé', this.newUser.username);
        this.showModal = false;
        this.newUser = { username: '', email: '', password: '', role: 'USER' };
        this.load();
      },
      error: () => this.toast.error('Erreur', 'Impossible de créer l\'utilisateur')
    });
  }

  deleteUser(u: any) {
    if (!confirm(`Supprimer l'utilisateur "${u.username}" ?`)) return;
    this.api.deleteUser(u.id).subscribe({
      next: () => { this.toast.success('Utilisateur supprimé'); this.load(); },
      error: () => this.toast.error('Erreur', 'Impossible de supprimer l\'utilisateur')
    });
  }
}
